#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $root = '/bench/repo';
my $module = 'github.com/usememos/memos';

# --- helpers ---
sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or return '';
    local $/;
    my $content = <$fh>;
    close $fh;
    return $content // '';
}

sub strip_comments {
    my ($s) = @_;
    $s =~ s{//[^\n]*}{}g;
    $s =~ s{/\*.*?\*/}{}gs;
    return $s;
}

sub dir_to_import_path {
    my ($dir) = @_;
    $dir =~ s{^\Q$root\E/?}{};
    return $module if $dir eq '';
    return "$module/$dir";
}

sub get_package_name {
    my ($content) = @_;
    if ($content =~ /^package\s+(\w+)/m) {
        return $1;
    }
    return '';
}

sub parse_imports {
    my ($content) = @_;
    my %alias_to_path;
    my %dot_paths;

    while ($content =~ /\bimport\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)"|(\w+)\s+"([^"]+)")/g) {
        my $block = $1;
        if (defined $2 && $2 ne '') {
            my $path = $2;
            my $alias = (split m{/}, $path)[-1];
            $alias =~ s/[^a-zA-Z0-9_]//g;
            $alias_to_path{$alias} = $path;
            next;
        }
        if (defined $4 && $4 ne '') {
            $alias_to_path{$3} = $4;
            next;
        }
        next unless defined $block;
        for my $line (split /\n/, $block) {
            $line =~ s{//.*}{};
            next if $line =~ /^\s*$/;
            if ($line =~ /^\s*\.\s+"([^"]+)"/) {
                $dot_paths{$1} = 1;
                next;
            }
            if ($line =~ /^\s*(\w+)\s+"([^"]+)"/) {
                $alias_to_path{$1} = $2;
            } elsif ($line =~ /^\s*"([^"]+)"/) {
                my $path = $1;
                my $alias = (split m{/}, $path)[-1];
                $alias =~ s/[^a-zA-Z0-9_]//g;
                $alias_to_path{$alias} = $path;
            }
        }
    }
    return (\%alias_to_path, \%dot_paths);
}

# --- collect all go files ---
my @all_go;
find(
    sub {
        return unless /\.go$/;
        return if $_ eq '.' && $File::Find::name !~ /\.go$/;
        push @all_go, $File::Find::name;
    },
    $root
);
@all_go = grep { $_ !~ m{/vendor/} } @all_go;

# --- declarations in internal/ ---
# pkg_func: path|name -> {file, symbol, kind}
# method: path|recv|name -> {file, symbol, kind}
my (%pkg_funcs, %methods, %methods_by_pkg_name, %file_pkg_path, %file_pkg_name, %file_dir);

for my $file (@all_go) {
    next unless $file =~ m{^\Q$root\E/internal/};
    my $content = read_file($file);
    my $dir = dirname($file);
    my $pkg_path = dir_to_import_path($dir);
    my $pkg = get_package_name($content);
    $file_pkg_path{$file} = $pkg_path;
    $file_pkg_name{$file} = $pkg;
    $file_dir{$file} = $dir;

    for my $line (split /\n/, $content) {
        next if $line =~ /^\s*\/\//;
        if ($line =~ /^\s*func\s+\(\s*[^)]*?\*?(\w+)\s*\)\s+(\w+)\s*[\(<]/) {
            my ($recv, $name) = ($1, $2);
            my $key = "$pkg_path|$recv|$name";
            $methods{$key} = {
                file   => $file,
                symbol => "($recv).$name",
                pkg    => $pkg_path,
                recv   => $recv,
                name   => $name,
                kind   => 'method',
            };
            push @{ $methods_by_pkg_name{"$pkg_path|$name"} }, $recv;
        } elsif ($line =~ /^\s*func\s+(\w+)\s*[\(<]/) {
            my $name = $1;
            my $key = "$pkg_path|$name";
            $pkg_funcs{$key} = {
                file   => $file,
                symbol => $name,
                pkg    => $pkg_path,
                name   => $name,
                kind   => 'func',
            };
        }
    }
}

# Go builtin / keywords that look like calls
my %not_calls = map { $_ => 1 } qw(
    if for switch select go defer return func make new len cap append copy delete
    close complex real imag panic recover print println struct interface map chan
    case default range break continue fallthrough goto else import package const var type
);

# --- count call sites ---
my %fanin;    # decl_key -> count
my %evidence; # decl_key -> [file:line, ...] sample

sub record_call {
    my ($decl_key, $file, $line_no) = @_;
    $fanin{$decl_key}++;
    push @{ $evidence{$decl_key} }, "$file:$line_no" if ($fanin{$decl_key} <= 5);
}

for my $file (@all_go) {
    my $raw = read_file($file);
    my $content = strip_comments($raw);
    my $dir = dirname($file);
    my $pkg_path = dir_to_import_path($dir);
    my ($imports, $dot_imports) = parse_imports($raw);

    my @lines = split /\n/, $content;
    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        my $line_no = $i + 1;

        # skip declarations
        next if $line =~ /^\s*func\s+/;
        next if $line =~ /^\s*type\s+/;

        # qualified calls: alias.Func(
        while ($line =~ /\b([a-zA-Z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($alias, $name) = ($1, $2);
            next if $not_calls{$name};
            my $imp = $imports->{$alias};
            next unless defined $imp && $imp =~ m{^\Q$module\E/internal/};
            my $fkey = "$imp|$name";
            if (exists $pkg_funcs{$fkey}) {
                record_call($fkey, $file, $line_no);
                next;
            }
            # method via package qualifier is rare (pkg.Type.Method) - skip
        }

        # dot-imported package calls: bare Func(
        for my $dot_path (keys %$dot_imports) {
            next unless $dot_path =~ m{^\Q$module\E/internal/};
            while ($line =~ /\b([A-Za-z_]\w*)\s*\(/g) {
                my $name = $1;
                next if $not_calls{$name};
                my $fkey = "$dot_path|$name";
                record_call($fkey, $file, $line_no) if exists $pkg_funcs{$fkey};
            }
        }

        # same-package unqualified calls
        if ($pkg_path =~ m{^\Q$module\E/internal/}) {
            while ($line =~ /(?<![.\w])([A-Za-z_]\w*)\s*\(/g) {
                my $name = $1;
                next if $not_calls{$name};
                my $fkey = "$pkg_path|$name";
                record_call($fkey, $file, $line_no) if exists $pkg_funcs{$fkey};
            }
        }

        # method calls: recv.Method(
        while ($line =~ /(?:\)|\]|'|"|`|\w)\s*\.\s*([A-Za-z_]\w*)\s*\(/g) {
            my $name = $1;
            next if $not_calls{$name};

            # same package methods
            if ($pkg_path =~ m{^\Q$module\E/internal/}) {
                my $list = $methods_by_pkg_name{"$pkg_path|$name"};
                if ($list && @$list == 1) {
                    my $recv = $list->[0];
                    my $mkey = "$pkg_path|$recv|$name";
                    record_call($mkey, $file, $line_no) if exists $methods{$mkey};
                }
            }

            # methods on types from imported internal packages - only if unique method in that pkg
            for my $alias (keys %$imports) {
                my $imp = $imports->{$alias};
                next unless $imp =~ m{^\Q$module\E/internal/};
                my $list = $methods_by_pkg_name{"$imp|$name"};
                next unless $list && @$list == 1;
                my $recv = $list->[0];
                my $mkey = "$imp|$recv|$name";
                record_call($mkey, $file, $line_no) if exists $methods{$mkey};
            }
        }

        # explicit &Type{}.Method or Type{}.Method - uncommon
        while ($line =~ /\b([A-Za-z_]\w*)\s*\{[^}]*\}\s*\.\s*([A-Za-z_]\w*)\s*\(/g) {
            my ($recv, $name) = ($1, $2);
            if ($pkg_path =~ m{^\Q$module\E/internal/}) {
                my $mkey = "$pkg_path|$recv|$name";
                record_call($mkey, $file, $line_no) if exists $methods{$mkey};
            }
        }
    }
}

# subtract self-declaration false positives? func Foo already skipped by declaration line check
# but same-line in func body of Foo calling Foo - that's valid

# Build ranked output
my @ranked;
for my $key (keys %pkg_funcs) {
    my $c = $fanin{$key} // 0;
    push @ranked, { %{$pkg_funcs{$key}}, key => $key, fanin => $c };
}
for my $key (keys %methods) {
    my $c = $fanin{$key} // 0;
    push @ranked, { %{$methods{$key}}, key => $key, fanin => $c };
}
@ranked = sort { $b->{fanin} <=> $a->{fanin} || $a->{symbol} cmp $b->{symbol} } @ranked;

print "TOP 25 internal symbols by direct call fan-in:\n";
for my $i (0 .. 24) {
    last unless $i < @ranked;
    my $r = $ranked[$i];
  printf "%3d  %6d  %-40s  %s\n", $i+1, $r->{fanin}, $r->{symbol}, $r->{file};
    if ($i < 3 && $r->{fanin} > 0) {
        my $ev = $evidence{$r->{key}} // [];
        print "       samples: ", join(', ', @$ev), "\n";
    }
}

print "\nTotal internal declarations: ", scalar(keys %pkg_funcs) + scalar(keys %methods), "\n";

