my(%pkg_funcs,%methods,%methods_by_pkg_name);
for my $file(@all_go){next unless $file=~m{^\Q$root\E/internal/}; my $content=read_file($file); my $pp=dir_to_import_path(dirname($file));
 for(split /\n/,$content){next if/^\s*\/\//; if(/^\s*func\s+\(\s*[^)]*?\*?(\w+)\s*\)\s+(\w+)\s*[\(<]/){my($r,$n)=($1,$2); $methods{"$pp|$r|$n"}={file=>$file,symbol=>"($r).$n",recv=>$r,name=>$n}; push @{$methods_by_pkg_name{"$pp|$n"}},$r}
  elsif(/^\s*func\s+(\w+)\s*[\(<]/){$pkg_funcs{"$pp|$1"}={file=>$file,symbol=>$1,name=>$1}}}}
my %kw=map{$_=>1}qw(if for switch select go defer return func make new len cap append copy delete close complex real imag panic recover print println struct interface map chan case default range break continue fallthrough goto else import package const var type);
my(%all,%prod,%test);
sub rec{my($k,$f,$ln,$prod)=@_; $all{$k}++; $prod{$k}++ if $prod; $test{$k}++ unless $prod}
