  while($l=~/\b([a-zA-Z_]\w*)\.([A-Za-z_]\w*)\s*\(/g){my($al,$n)=($1,$2); next if $kw{$n}; my $p=$imp->{$al}; next unless defined$p&&$p=~m{^\Q$module\E/internal/}; rec("$p|$n",$f,$ln,$is_prod) if exists $pkg_funcs{"$p|$n"}}
  for(keys %$dot){next unless $_=~m{^\Q$module\E/internal/}; while($l=~/\b([A-Za-z_]\w*)\s*\(/g){my $n=$1; next if $kw{$n}; rec("$_|$n",$f,$ln,$is_prod) if exists $pkg_funcs{"$_|$n"}}}
