   for(keys %$imp){my $p=$imp->{$_}; next unless $p=~m{^\Q$module\E/internal/}; my $L=$methods_by_pkg_name{"$p|$n"}; next unless $L&&@$L==1; rec("$p|$L->[0]|$n",$f,$ln,$is_prod) if exists $methods{"$p|$L->[0]|$n"}}}
 }}
my @ranked;
for my $k(keys %pkg_funcs){push @ranked,{%{ $pkg_funcs{$k}},key=>$k,all=>$all{$k}//0,prod=>$prod{$k}//0,test=>$test{$k}//0}}
for my $k(keys %methods){push @ranked,{%{ $methods{$k}},key=>$k,all=>$all{$k}//0,prod=>$prod{$k}//0,test=>$test{$k}//0}}
@ranked=sort{$b->{prod}<=>$a->{prod}||$b->{all}<=>$a->{all}}@ranked;
print "TOP 20 by PRODUCTION call sites (excl *_test.go):\n";
